package ec.edu.unl.sec.evidence.domain;import static org.assertj.core.api.Assertions.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;class EvidenceDraftTest{UUID evidence=UUID.randomUUID(),version=UUID.randomUUID(),indicator=UUID.randomUUID(),actor=UUID.randomUUID();@Test void createsStableLineageAndValidDraft(){var root=new Evidence(null,UUID.randomUUID(),actor,Instant.now(),UUID.randomUUID(),0);var draft=draft(List.of(new VersionIndicator(version,indicator,"I-1","Indicador",1)));assertThat(root.latestRevision()).isZero();assertThat(draft.revisionNumber()).isEqualTo(1);assertThat(draft.status()).isEqualTo(EvidenceVersionStatus.DRAFT);}@Test void rejectsInvalidRangesDatesPredecessorAndDuplicateIndicators(){var i=new VersionIndicator(version,indicator,"I","Indicador",1);assertThatThrownBy(()->draft(List.of(i,new VersionIndicator(version,indicator,"I","Indicador",2)))).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->new EvidenceVersion(version,evidence,1,UUID.randomUUID(),EvidenceVersionStatus.DRAFT,"T","D","P",LocalDate.now(),LocalDate.now(),actor,Instant.now(),null,0,List.of(i))).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->new EvidenceVersion(version,evidence,1,null,EvidenceVersionStatus.DRAFT,"T","D","P",LocalDate.now(),LocalDate.now().minusDays(1),actor,Instant.now(),null,0,List.of(i))).isInstanceOf(IllegalArgumentException.class);}@Test void submittedDraftCannotBeUpdated(){var i=new VersionIndicator(version,indicator,"I","Indicador",1);var submitted=new EvidenceVersion(version,evidence,1,null,EvidenceVersionStatus.SUBMITTED,"T","D","P",LocalDate.now(),LocalDate.now(),actor,Instant.now(),Instant.now(),0,List.of(i));assertThatThrownBy(()->submitted.update("T","D","P",LocalDate.now(),LocalDate.now(),List.of(i))).isInstanceOf(IllegalStateException.class);}private EvidenceVersion draft(List<VersionIndicator> indicators){return new EvidenceVersion(version,evidence,1,null,EvidenceVersionStatus.DRAFT,"Título","Descripción","Procedencia",LocalDate.now(),LocalDate.now(),actor,Instant.now(),null,0,indicators);}}
